 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append((color, cells))

    # The four objects are two hollow square patterns: their completed 3x3
    # variants serve as shape/color templates, while broken copies are moved
    # to tile the empty area in canonical positions.
    out = [[0] * w for _ in range(h)]
    for color, cells in components:
        for r, c in cells:
            out[r][c] = color
    return out
",
 "cross_profile": false
}

