 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    # Extract each connected non-background shape, its local footprint, and
    # whether it encloses any zero cells. Enclosed shapes rise; open shapes fall.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            y0 = min(y for y, x in cells)
            x0 = min(x for y, x in cells)
            y1 = max(y for y, x in cells)
            x1 = max(x for y, x in cells)
            occupied = set(cells)
            empty = {(y, x) for y in range(y0, y1 + 1)
                     for x in range(x0, x1 + 1) if (y, x) not in occupied}
            outside = set()
            queue = [p for p in empty if p[0] in (y0, y1) or p[1] in (x0, x1)]
            outside.update(queue)
            while queue:
                y, x = queue.pop()
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (yy, xx) in empty and (yy, xx) not in outside:
                        outside.add((yy, xx))
                        queue.append((yy, xx))

            objects.append({
                'color': color,
                'x': x0,
                'y': y0,
                'height': y1 - y0 + 1,
                'mask': frozenset((y - y0, x - x0) for y, x in cells),
                'closed': bool(empty - outside),
            })

    # Let each set of shapes fall/rise under gravity. Shapes are processed
    # from the direction-facing edge first, so they stack without changing
    # their horizontal location or silhouette.
    settled = []

    def cells_at(obj, top):
        return {(top + dy, obj['x'] + dx) for dy, dx in obj['mask']}

    def free(obj, top, prior):
        points = cells_at(obj, top)
        if any(y < 0 or y >= h or x < 0 or x >= w for y, x in points):
            return False
        return all(not (points & cells_at(other, other_top))
                   for other, other_top in prior)

    for group, direction in (
        (sorted((o for o in objects if o['closed']), key=lambda o: (o['y'], o['x'])), -1),
        (sorted((o for o in objects if not o['closed']), key=lambda o: (-o['y'], o['x'])), 1),
    ):
        prior = []
        for obj in group:
            top = obj['y']
            while free(obj, top + direction, prior):
                top += direction
            prior.append((obj, top))
        settled.extend(prior)

    output = [[0] * w for _ in range(h)]
    # In case two different gravity groups share a cell, the downward-moving
    # motif is drawn last, matching the demonstrations' overlap precedence.
    for obj, top in settled:
        if obj['closed']:
            for dy, dx in obj['mask']:
                output[top + dy][obj['x'] + dx] = obj['color']
    for obj, top in settled:
        if not obj['closed']:
            for dy, dx in obj['mask']:
                output[top + dy][obj['x'] + dx] = obj['color']
    return output
