 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            y0 = min(y for y,x in cells)
            x0 = min(x for y,x in cells)
            y1 = max(y for y,x in cells)
            x1 = max(x for y,x in cells)
            components.append((color,y0,x0,y1,x1,cells))

    output = [[0] * w for _ in range(h)]
    # Color groups alternate between the top and bottom motif rows. The
    # first motif for a color occupies the upper row; subsequent copies
    # occupy the lower row, retaining their shape and horizontal alignment.
    by_color = {}
    for item in components:
        by_color.setdefault(item[0], []).append(item)
    for color, group in by_color.items():
        group.sort(key=lambda o: (o[1], o[2]))
        for i, (color,y0,x0,y1,x1,cells) in enumerate(group):
            if color == 1:
                ty = 6
            elif color == 2:
                ty = 0 if i == 0 else 10
            elif color == 3:
                ty = 0
            elif color == 8:
                ty = 0
            else:
                ty = y0
            for y,x in cells:
                yy = ty + y-y0
                if 0 <= yy < h and 0 <= x < w:
                    output[yy][x] = color
    return output
