                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (yy,xx) in empty and (yy,xx) not in outside:
                        outside.add((yy,xx)); queue.append((yy,xx))
            objects.append({'color':color, 'cells':cells, 'y0':y0,
                            'closed':bool(empty-outside)})

    placed = []
    def shifted_cells(obj, top):
        delta = top - obj['y0']
        return {(y+delta,x) for y,x in obj['cells']}

    for is_closed, direction in ((True,-1),(False,1)):
        group = [o for o in objects if o['closed'] == is_closed]
        group.sort(key=lambda o: o['y0'] if direction < 0 else -o['y0'])
        settled = []
        for obj in group:
            top = obj['y0']
            while True:
                nxt = top + direction
                cells = shifted_cells(obj,nxt)
                if any(y < 0 or y >= h for y,x in cells):
                    break
                if any(cells & shifted_cells(other, other_top) for other,other_top in settled):
                    break
                top = nxt
            settled.append((obj,top))
        placed.extend(settled)

    out = [[0]*w for _ in range(h)]
