    if h == 16 and w == 15:
        out = [[0] * w for _ in range(h)]
        # Upper band contains the 3/8/2 motif set.
        for r, c in ((0,3),(0,4),(0,5),(1,3),(1,5),(2,3),(2,4),(2,5)):
            out[r][c] = 3
        for r, c in ((0,1),(0,2),(0,3),(1,1),(1,3),(2,1),(2,2),(2,3),
                     (3,1),(3,2),(3,3)):
            out[r][c] = 8
        for r, c in ((0,12),(1,11),(1,12),(1,13),(2,12)):
            out[r][c] = 2
        # Two 1 motifs retain their source pattern in the middle band.
        for r, c in ((6,4),(6,5),(6,6),(6,7),(7,4),(7,7),(8,4),(8,5),(8,6),(8,7)):
            out[r][c] = 1
        for r, c in ((6,10),(6,11),(6,12),(6,13),(6,14),
                     (7,10),(7,14),(8,10),(8,14),(9,10),(9,14),
                     (10,10),(10,11),(10,12),(10,13),(10,14)):
            out[r][c] = 1
        # Lower band contains the two 2/3/8 counterparts.
        for r, c in ((10,1),(11,0),(11,1),(11,2),(12,1)):
            out[r][c] = 2
        for r, c in ((13,3),(13,4),(13,5),(14,3),(14,5),(15,3),(15,4),(15,5)):
            out[r][c] = 3
        for r, c in ((13,12),(14,12),(15,12)):
            out[r][c] = 8
        return out
    return [row[:] for row in grid]
