 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            y0 = min(y for y, x in cells)
            x0 = min(x for y, x in cells)
            y1 = max(y for y, x in cells)
            x1 = max(x for y, x in cells)
            occupied = set(cells)
            empty = {(y, x) for y in range(y0, y1 + 1)
                     for x in range(x0, x1 + 1) if (y, x) not in occupied}
            outside = set()
            queue = [p for p in empty if p[0] in (y0, y1) or p[1] in (x0, x1)]
            outside.update(queue)
            while queue:
                y, x = queue.pop()
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (yy, xx) in empty and (yy, xx) not in outside:
                        outside.add((yy, xx))
                        queue.append((yy, xx))

            objects.append({
                'color': color,
                'cells': cells,
                'y0': y0,
                'x0': x0,
                'closed': bool(empty - outside),
            })

    # Closed shapes rise, while open shapes fall. Objects keep their columns
    # and stack against other objects in the same group without overlapping.
    placed = []

    def shifted_cells(obj, top):
        offset = top - obj['y0']
        return {(y + offset, x) for y, x in obj['cells']}

    for is_closed, direction in ((True, -1), (False, 1)):
        group = [obj for obj in objects if obj['closed'] == is_closed]
        if direction < 0:
            group.sort(key=lambda obj: (obj['y0'], obj['x0']))
        else:
            group.sort(key=lambda obj: (-obj['y0'], obj['x0']))

        settled = []
        for obj in group:
            top = obj['y0']
            while True:
                next_top = top + direction
                cells = shifted_cells(obj, next_top)
                if any(y < 0 or y >= h for y, x in cells):
                    break
                if any(cells & shifted_cells(other, other_top)
                       for other, other_top in settled):
                    break
                top = next_top
            settled.append((obj, top))
        placed.extend(settled)

    output = [[0] * w for _ in range(h)]
    for obj, top in placed:
        for y, x in shifted_cells(obj, top):
            output[y][x] = obj['color']
    return output
