    up = sorted((o for o in objects if o["up"]), key=lambda o: (o["y0"], o["x0"]))
    fixed = []
    for o in up:
        while o["top"] > 0 and not any(bbox_overlap(o, o["top"] - 1, p, p["top"]) for p in fixed):
